'use strict';
let liveMap=null,liveLayers=null,gpsWatch=null,gpsOwner='',gpsGeneration=0,gpsPosition=null,gpsMessage='GPS o‘chiq. Joylashuv faqat siz yoqqaningizda olinadi.',gpsLastPublish=0;
function routeOrder(){return courierState.orders.find(o=>o.id===courierRouteId&&o.delivery?.courierId===courierId)||courierActiveOrders(courierState,courierId)[0]||courierState.orders.find(o=>o.delivery?.courierId===courierId)||null;}
function gpsControls(){return `<div class="gps-controls">${courierButton(gpsWatch===null?'GPSni yoqish va sotuvchiga ulashish':'GPSni o‘chirish',gpsWatch===null?'gps-start':'gps-stop','','primary')}${courierButton('Mening joyimga','gps-center')}${courierButton('Barcha nuqtalar','gps-fit')}</div><p class="gps-status" id="gps-status" role="status">${esc(gpsMessage)}</p>`;}
courierRoute=function(){const o=routeOrder(),owned=courierState.orders.filter(o=>o.delivery?.courierId===courierId),b=o?courierBranchInfo(o.branch):null;return `<div class="page-title"><div><h1>Xarita va GPS</h1><p class="subtitle">Jonli qurilma nuqtasi, restoran va mijoz manzillari.</p></div></div>${gpsControls()}<p class="metric-note">GPS yoqilganda oxirgi joylashuv shu brauzerdagi sotuvchi paneliga ulashiladi. To‘liq yo‘l tarixi saqlanmaydi. Xarita OpenStreetMap rasmlaridan foydalanadi.</p>${owned.length?`<div class="filter-row"><select id="courier-route-order" aria-label="Xaritadagi buyurtma">${owned.map(x=>`<option value="${esc(x.id)}" ${x.id===o?.id?'selected':''}>#${esc(x.id.slice(0,12))}</option>`).join('')}</select></div>`:''}<div id="courier-live-map" class="live-map" aria-label="Restoran, mijoz va kuryer xaritasi"></div><div class="map-legend"><span><b>R</b> Restoran</span><span><b>M</b> Mijoz</span><span><b>GPS</b> Siz va aniqlik doirasi</span></div>${o?`<div class="panel"><h2>#${esc(o.id.slice(0,12))}</h2><p><strong>Restoran:</strong> ${esc(b?.address||'—')} · ${geoLabel(o.pickupLocation)}</p><p><strong>Mijoz:</strong> ${esc(o.deliveryAddress)} · ${geoLabel(o.dropoffLocation)}</p>${courierDetails(o)}<div class="card-actions">${courierDirection(o.pickupLocation?o.pickupLocation.lat+','+o.pickupLocation.lng:b?.address,'Restoranga yo‘l')}${courierDirection(o.dropoffLocation?o.dropoffLocation.lat+','+o.dropoffLocation.lng:o.deliveryAddress,'Mijozga yo‘l')}</div><p class="metric-note">Xaritadagi chiziq nuqtalarni to‘g‘ri bog‘laydi, avtomobil yo‘li emas. Ko‘cha bo‘ylab yo‘nalish uchun “Yo‘l” tugmasini bosing. Koordinata bo‘lmasa, sotuvchi “Yetkazish” formasidagi xaritada uni belgilaydi.</p></div>`:courierEmpty('GPSni buyurtmasiz ham smena paytida yoqishingiz mumkin. Restoran va mijoz nuqtalari buyurtma olingach ko‘rinadi.')}`;};
function updateGpsText(){const el=$('#gps-status');if(el)el.textContent=gpsMessage;}
function drawCourierMap(fit=false){if(!liveMap||!globalThis.L)return;liveLayers.clearLayers();const o=routeOrder(),points=[];for(const [p,label] of [[o?.pickupLocation,'R · Restoran'],[o?.dropoffLocation,'M · Mijoz']]){if(!p||!geoPoint(p.lat,p.lng))continue;points.push([p.lat,p.lng]);L.marker([p.lat,p.lng]).addTo(liveLayers).bindTooltip(label);}if(points.length===2)L.polyline(points,{color:'#7129e5',weight:3,dashArray:'7 8'}).addTo(liveLayers);if(gpsPosition){const p=gpsPosition;points.push([p.lat,p.lng]);L.circleMarker([p.lat,p.lng],{radius:9,color:'#fff',weight:3,fillColor:'#1677e8',fillOpacity:1}).addTo(liveLayers).bindTooltip('GPS · Siz');L.circle([p.lat,p.lng],{radius:p.accuracy,color:'#1677e8',weight:1,fillOpacity:.08}).addTo(liveLayers);}if(fit&&points.length){if(points.length===1)liveMap.setView(points[0],16);else liveMap.fitBounds(points,{padding:[35,35],maxZoom:16});}}
function mountCourierMap(){const container=$('#courier-live-map');if(!container||!container.isConnected)return;if(!globalThis.L){container.innerHTML='<div class="map-offline">Xarita kutubxonasi yuklanmadi. Internetni tekshiring. GPS koordinatasini matnda ko‘rish mumkin.</div>';return;}liveMap=L.map(container).setView([41.3111,69.2797],12);liveLayers=L.layerGroup().addTo(liveMap);const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'}).addTo(liveMap);tiles.on('tileerror',()=>{gpsMessage='Xarita rasmlari yuklanmadi. Internetni tekshiring; GPS alohida ishlashi mumkin.';updateGpsText();});drawCourierMap(true);}
async function stopCourierGps(persist=true){const owner=gpsOwner;gpsGeneration++;if(gpsWatch!==null)navigator.geolocation?.clearWatch(gpsWatch);gpsWatch=null;gpsOwner='';gpsPosition=null;gpsMessage='GPS o‘chirildi. Sotuvchiga joylashuv ulashish to‘xtatildi.';if(persist&&owner)try{courierState=await courierTransaction(owner,'gps','',{enabled:false});}catch{}updateGpsText();drawCourierMap();}
function startCourierGps(){if(gpsWatch!==null)return;if(courierWork(courierPerson())!=='working'){courierToast('GPS uchun avval smenani boshlang.');return;}if(!navigator.geolocation){gpsMessage='Brauzer GPSni qo‘llamaydi.';updateGpsText();return;}if(globalThis.isSecureContext===false){gpsMessage='GPS uchun HTTPS yoki localhost manzilidan foydalaning.';updateGpsText();return;}const generation=++gpsGeneration,owner=courierId;gpsOwner=owner;gpsLastPublish=0;gpsMessage='GPS ruxsati va joylashuv kutilmoqda…';updateGpsText();gpsWatch=navigator.geolocation.watchPosition(async p=>{if(generation!==gpsGeneration||courierId!==owner)return;const point=geoPoint(p.coords.latitude,p.coords.longitude);if(!point||!Number.isFinite(p.coords.accuracy))return;const first=!gpsPosition;gpsPosition={...point,accuracy:p.coords.accuracy};gpsMessage=`GPS: ${geoLabel(point)} · aniqlik ±${Math.round(p.coords.accuracy)} m · ${new Date().toLocaleTimeString('uz-UZ')}`;updateGpsText();drawCourierMap();if(first&&liveMap)liveMap.setView([point.lat,point.lng],16);if(Date.now()-gpsLastPublish>=10000){gpsLastPublish=Date.now();try{const fresh=await courierTransaction(owner,'gps','',{...gpsPosition,enabled:true});if(generation===gpsGeneration)courierState=fresh;}catch(error){gpsMessage=error.message;updateGpsText();}}},error=>{if(generation!==gpsGeneration)return;gpsMessage=error.code===1?'GPS ruxsati berilmadi. Brauzer manzil satridagi joylashuv ruxsatini tekshiring.':error.code===2?'Qurilma joylashuvni aniqlay olmadi.':'GPS vaqti tugadi. Ochiq joyda qayta sinang.';if(error.code===1){stopCourierGps().then(()=>{gpsMessage='GPS ruxsati berilmadi. Brauzerdan ruxsat bering va qayta yoqing.';courierRender();});}updateGpsText();},{enableHighAccuracy:true,timeout:20000,maximumAge:5000});courierRender();}
var mapBaseCard=courierCard;
courierCard=function(o,mode){let html=mapBaseCard(o,mode);if(mode==='active'&&o.delivery.status==='assigned'){const confirmed=!!o.delivery.handoffConfirmedAt,atRestaurant=courierPhase(o)==='at_restaurant';html=html.replace('</article>',`<div class="handoff-code"><div><strong>${esc(o.delivery.handoffCode||'—')}</strong><p>Kodni faqat buyurtmani topshirayotgan sotuvchiga ko‘rsating.</p></div><span class="tag ${confirmed?'success':'warning'}">${confirmed?'Sotuvchi tasdiqladi':atRestaurant?'Sotuvchi tasdig‘i kutilmoqda':'Avval restoranga boring'}</span></div></article>`);if(!confirmed)html=html.replace('data-action="confirm-pickup"','disabled data-action="confirm-pickup"');}return html;};
var mapBaseRender=courierRender;
courierRender=function(){if(liveMap){liveMap.remove();liveMap=null;liveLayers=null;}if(gpsWatch!==null&&(gpsOwner!==courierId||courierWork(courierPerson()||{})!=='working'))stopCourierGps();mapBaseRender();if(courierPage==='route')mountCourierMap();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||!['gps-start','gps-stop','gps-center','gps-fit'].includes(b.dataset.action))return;e.preventDefault();e.stopImmediatePropagation();if(b.dataset.action==='gps-start')startCourierGps();if(b.dataset.action==='gps-stop')stopCourierGps().then(()=>courierRender());if(b.dataset.action==='gps-center'){if(gpsPosition&&liveMap)liveMap.setView([gpsPosition.lat,gpsPosition.lng],16);else courierToast('Avval GPSni yoqing va nuqta kelishini kuting.');}if(b.dataset.action==='gps-fit')drawCourierMap(true);},true);
window.addEventListener('pagehide',()=>{const owner=gpsOwner;stopCourierGps(false);if(owner)try{const s=courierRead(),c=s.couriers.find(c=>c.id===owner);if(c){c.gpsSharing=false;delete c.location;localStorage.setItem(COURIER_STORE,JSON.stringify(s));}}catch{}});
courierRender();
